export const TEMPLATE_VARIABLES = [
  'first_name',
  'title',
  'number',
  'amount_due',
  'due_date',
  'days_overdue',
  'link',
  'business_name',
  'late_fee_notice',
] as const;
export type TemplateVariable = (typeof TEMPLATE_VARIABLES)[number];

export function renderTemplate(template: string, vars: Partial<Record<string, string>>): string {
  return template
    .replace(/\{(\w+)\}/g, (_, key: string) => vars[key] ?? '')
    .replace(/[ \t]{2,}/g, ' ')
    .replace(/ +([.,!?])/g, '$1')
    .trim();
}

export function firstName(fullName: string | null | undefined): string {
  const first = (fullName ?? '').trim().split(/\s+/)[0];
  return first || 'there';
}

export function lateFeeNotice(lateFee: LateFeeSettings | null | undefined, balanceCents: number, currency: string, locale: string): string {
  if (!lateFee?.enabled || lateFee.amount <= 0) return '';
  const fee = lateFee.kind === 'flat' ? lateFee.amount : percentOfCents(balanceCents, lateFee.amount);
  if (fee <= 0) return '';
  return ` A late fee of ${formatMoney(fee, currency, locale)} may be added if it remains unpaid.`;
}

export interface ChaseVariableInput {
  customerName: string | null;
  businessName: string;
  title: string;
  number: string | null;
  balanceCents: number;
  currency: string;
  locale: string;
  dueAt: string | null;
  link: string;
  lateFee?: LateFeeSettings | null;
  now?: Date;
  timeZone?: string;
}

export function buildChaseVariables(input: ChaseVariableInput): Record<TemplateVariable, string> {
  const now = input.now ?? new Date();
  const due = input.dueAt ? new Date(input.dueAt) : null;
  const daysOverdue = due ? Math.max(0, Math.floor((now.getTime() - due.getTime()) / DAY_MS)) : 0;
  return {
    first_name: firstName(input.customerName),
    title: input.title,
    number: input.number ?? '',
    amount_due: formatMoney(input.balanceCents, input.currency, input.locale),
    due_date: due
      ? new Intl.DateTimeFormat(input.locale, { dateStyle: 'medium', timeZone: input.timeZone }).format(due)
      : 'receipt',
    days_overdue: String(daysOverdue),
    link: input.link,
    business_name: input.businessName,
    late_fee_notice: lateFeeNotice(input.lateFee, input.balanceCents, input.currency, input.locale),
  };
}

/** US/CA carrier rules (A2P 10DLC) expect opt-out language on business SMS. */
export function smsOptOutSuffix(country: Country): string {
  return country === 'US' || country === 'CA' ? ' Reply STOP to opt out.' : '';
}

// ---------------------------------------------------------------------------------------------
// Time-zone helpers (no dependencies; work in Deno, Node and Hermes).

interface ZonedParts {
  year: number;
  month: number;
  day: number;
  hour: number;
  minute: number;
  second: number;
}

const partFormatters = new Map<string, Intl.DateTimeFormat>();

export function zonedParts(date: Date, timeZone: string): ZonedParts {
  let fmt = partFormatters.get(timeZone);
  if (!fmt) {
    fmt = new Intl.DateTimeFormat('en-US', {
      timeZone,
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      hourCycle: 'h23',
    });
    partFormatters.set(timeZone, fmt);
  }
  const out: Record<string, number> = {};
  for (const part of fmt.formatToParts(date)) {
    if (part.type !== 'literal') out[part.type] = Number(part.value);
  }
  return {
    year: out.year!,
    month: out.month!,
    day: out.day!,
    hour: out.hour! % 24,
    minute: out.minute!,
    second: out.second!,
  };
}

function offsetMs(date: Date, timeZone: string): number {
  const p = zonedParts(date, timeZone);
  const asUtc = Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second);
  return asUtc - Math.floor(date.getTime() / 1000) * 1000;
}

/** Converts a wall-clock time in `timeZone` to the UTC instant (handles DST transitions). */
export function zonedTimeToUtc(year: number, month: number, day: number, hour: number, minute: number, timeZone: string): Date {
  const guess = Date.UTC(year, month - 1, day, hour, minute);
  const first = offsetMs(new Date(guess), timeZone);
  let utc = guess - first;
  const second = offsetMs(new Date(utc), timeZone);
  if (second !== first) utc = guess - second;
  return new Date(utc);
}

export function isQuietHours(
  date: Date,
  timeZone: string,
  startHour = DEFAULT_QUIET_START_HOUR,
  endHour = DEFAULT_QUIET_END_HOUR,
): boolean {
  if (startHour === endHour) return false;
  const { hour } = zonedParts(date, timeZone);
  return startHour > endHour ? hour >= startHour || hour < endHour : hour >= startHour && hour < endHour;
}

/** Earliest instant ≥ `date` outside quiet hours (moves to `endHour`:00 local). */
export function nextAllowedSendTime(
  date: Date,
  timeZone: string,
  startHour = DEFAULT_QUIET_START_HOUR,
  endHour = DEFAULT_QUIET_END_HOUR,
): Date {
  if (!isQuietHours(date, timeZone, startHour, endHour)) return date;
  const p = zonedParts(date, timeZone);
  const nextDay = startHour > endHour && p.hour >= startHour;
  const base = new Date(Date.UTC(p.year, p.month - 1, p.day + (nextDay ? 1 : 0)));
  return zonedTimeToUtc(base.getUTCFullYear(), base.getUTCMonth() + 1, base.getUTCDate(), endHour, 0, timeZone);
}

export interface PlannedChaseJob {
  step_index: number;
  scheduled_for: Date;
  channel: ChaseStep['channel'];
  tone: ChaseStep['tone'];
}

/** Chase steps are anchored on the due date (which equals the sent date for "due on receipt"). */
export function planChaseJobs(
  anchor: Date,
  steps: readonly ChaseStep[],
  timeZone: string,
  quiet: { startHour?: number; endHour?: number } = {},
): PlannedChaseJob[] {
  return steps.map((step, index) => ({
    step_index: index,
    channel: step.channel,
    tone: step.tone,
    scheduled_for: nextAllowedSendTime(
      new Date(anchor.getTime() + step.day_offset * DAY_MS),
      timeZone,
      quiet.startHour ?? DEFAULT_QUIET_START_HOUR,
      quiet.endHour ?? DEFAULT_QUIET_END_HOUR,
    ),
  }));
}
